parameters.jsCode:
// Split the extractor output into two streams: signals + content_ideas.
// We emit a unified item shape with `kind` so the IF node below can route.

const raw = $('Extract Signals + Ideas').item.json.message.content;
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  // Bad JSON — log to audit and bail.
  return [{ json: { kind: 'parse_error', raw, error: e.message } }];
}

const trig = $('Drive Trigger: Signal Inbox folder').item.json;
const driveLink = trig.webViewLink || `https://drive.google.com/file/d/${trig.id}/view`;
const fileId = trig.id;
const fileName = trig.name;
const capturedAt = trig.createdTime || new Date().toISOString();

const out = [];

for (const s of (parsed.signals || [])) {
  out.push({ json: {
    kind: 'signal',
    payload: {
      signal_type: s.signal_type || 'other',
      venture: s.venture || 'shared',
      company_name: s.company_name || null,
      contact_name: s.contact_name || null,
      description: s.description,
      source_url: s.source_url || driveLink,
      signal_score: s.signal_score || 5,
      summary: s.summary || null,
      raw_data: { from: 'signal_inbox', drive_file_id: fileId, drive_file_name: fileName },
      status: 'new',
      surfaced_at: capturedAt,
    }
  }});
}

for (const i of (parsed.content_ideas || [])) {
  out.push({ json: {
    kind: 'idea',
    payload: {
      source_type: 'signal_inbox',
      source_ref: fileId,
      source_url: driveLink,
      source_snippet: i.source_snippet || null,
      raw_text: JSON.stringify({ idea: i.idea, thesis: i.thesis, distribution: i.distribution || [], confidence: i.confidence }),
      captured_at: capturedAt,
    }
  }});
}

// If nothing extracted, emit a single noop row so downstream merge still sees a result
if (out.length === 0) {
  out.push({ json: { kind: 'noop', file: fileName, fileId } });
}

return out;
